  ('30000000-0000-4000-8000-000000000004', 'כתיבת אירועים', 'איך כותבים תיאור אירוע עובדתי, ברור ומקצועי.', '10000000-0000-4000-8000-000000000509', 'https://example.com/replace-me', null, null, null, 45, false, array[]::public.app_role[], array['כתיבה', 'דיווח', 'אירוע', 'תלם']::text[], 40, null, '2026-09-01T08:00:00.000Z', '2026-09-01T08:00:00.000Z'),
