  ('40000000-0000-4000-8000-000000000001', 'ברוכים הבאים לטוקאייר במקום אחד', 'כל המערכות, הנהלים, הטפסים וההדרכות מרוכזים עכשיו במקום אחד. אם חסר קישור או שמשהו לא עובד, עדכנו את ההנהלה.', 'management', true, '2026-09-24T07:00:00.000Z', array[]::public.app_role[], null, null, null, 'הנהלת הכפר', '2026-09-24T07:00:00.000Z', '2026-09-24T07:00:00.000Z'),
