  ('40000000-0000-4000-8000-000000000003', 'דוגמה להודעה תפעולית', 'כאן יופיעו הודעות שוטפות: שינויים במשמרות, תחזוקה, אירועים בכפר.', 'operational', false, '2026-09-15T09:00:00.000Z', array[]::public.app_role[], null, null, null, 'הנהלת הכפר', '2026-09-15T09:00:00.000Z', '2026-09-15T09:00:00.000Z')
